const raw = $input.first().json;
// Agar data body ke andar ho (webhook payload) to usay unpack karein
const item = raw.body ? raw.body : raw;

// Email, Phone ya standard WhatsApp fields extract karein
const contact = item.contact || item.email || item.phone || item.From || item.from || '';

// Message string ya nested text nikaalein
let messageText = '';
if (item.text && item.text.body) {
  messageText = item.text.body;
} else if (typeof item.message === 'string') {
  messageText = item.message;
} else if (typeof item.Body === 'string') {
  messageText = item.Body;
} else {
  messageText = String(item.message || item.Body || '');
}

return [{
  json: {
    contact: String(contact).trim(),
    message: String(messageText).trim(),
    source: raw.source || item.source || 'website_form',
    timestamp: new Date().toISOString()
  }
}];

