// 1. AI Scoring Agent ka JSON parse karein
const aiOutput = JSON.parse($('AI Lead Scoring Agent').item.json.message.content);

// 2. Customer contact aur message lein
const contact = $('Format Lead Payload').item.json.contact;
const customerMessage = ($('Format Lead Payload').item.json.message || '').toLowerCase();

// 3. Agent Roster se fetched agents nikalain (fields ke andar se)
const agents = $('Get Agent Roster').all().map(a => a.json.fields || a.json);

// 4. Territory match karein (e.g. DHA)
let assigned = agents.find(a => a.Territory && customerMessage.includes(a.Territory.toLowerCase()));

// Agar territory match na ho to pehla available agent assign karein
if (!assigned && agents.length > 0) {
  assigned = agents[0];
}

const agentName = assigned ? assigned.Name : 'General Team';
const agentPhone = assigned ? assigned.Phone : '';

return [{
  json: {
    contact,
    customerMessage,
    leadScore: aiOutput.lead_score,
    replyMessage: aiOutput.reply_message,
    assignedAgent: agentName,
    agentPhone: agentPhone,
    matchReason: aiOutput.reasoning
  }
}];

